const treeStats=value=>{const stats={nodes:0,bytes:0,maxDepth:0,maxWidth:0,maxArray:0},visit=(node,depth)=>{stats.nodes++;stats.maxDepth=Math.max(stats.maxDepth,depth);if(typeof node==='string')stats.bytes+=Buffer.byteLength(node);else if(Array.isArray(node)){stats.maxArray=Math.max(stats.maxArray,node.length);node.forEach(child=>visit(child,depth+1));}else if(node&&typeof node==='object'){stats.maxWidth=Math.max(stats.maxWidth,Object.keys(node).length);for(const [name,child] of Object.entries(node)){stats.bytes+=Buffer.byteLength(name);visit(child,depth+1);}}};visit(value,0);return stats;};
