test('flat volume aggregates distinct hours and requires equal positive consecutive run',()=>{const h=n=>`2026-08-17T${String(n).padStart(2,'0')}:00:00.000Z`,flat=a=>analyzeCompliance({fetches:a}).signals.some(s=>s.code==='flat_volume_pattern');assert.equal(flat([vf(h(10),1,'a'),vf(h(10),1,'b'),vf(h(10),1,'c')]),false,'duplicates are one bucket');assert.equal(flat([vf(h(10),2),vf(h(12),2),vf(h(13),2)]),false,'gap');assert.equal(flat([vf(h(10),2),vf(h(11),3),vf(h(12),2)]),false,'non-equal');assert.equal(flat([vf(h(10),2),vf(h(11),2),vf(h(12),2)]),true,'valid run');assert.equal(flat([vf(h(10),1,'a'),vf(h(10),1,'b'),vf(h(11),2),vf(h(12),2)]),true,'same-hour aggregation');});
